  function selectPatient(id) {
    currentPatientId = id;
    render();
  }

  function addVisit() {
    const noteEl = document.getElementById("newNote");
    const note = noteEl.value.trim();
    if (!note) { noteEl.focus(); return; }
    const p = state.patients.find(x => x.id === currentPatientId);
    if (!p) return;
    p.visits.unshift({ id: uid(), date: new Date().toISOString(), note });
    noteEl.value = "";
    save();
    render();
    toast("Visit saved");
  }

  function deleteVisit(visitId) {
    const p = state.patients.find(x => x.id === currentPatientId);
    if (!p) return;
    if (!confirm("Delete this visit note?")) return;
    p.visits = p.visits.filter(v => v.id !== visitId);
    save();
    render();
    toast("Visit deleted");
  }

  function editVisit(visitId) {
    const p = state.patients.find(x => x.id === currentPatientId);
    if (!p) return;
    const v = p.visits.find(x => x.id === visitId);
