      const li = document.createElement("li");
      if (p.id === currentPatientId) li.classList.add("active");
      li.innerHTML = `<span>${escapeHtml(p.name)}</span><span class="count">${p.visits.length}</span>`;
      li.onclick = () => selectPatient(p.id);
      list.appendChild(li);
    });

    // Main panel
    const noPatient = document.getElementById("noPatient");
    const patientView = document.getElementById("patientView");
    const p = state.patients.find(x => x.id === currentPatientId);

    if (!p) {
      noPatient.style.display = "";
      patientView.style.display = "none";
      return;
    }
    noPatient.style.display = "none";
    patientView.style.display = "";

    document.getElementById("currentPatientName").textContent = p.name;
    document.getElementById("todayDate").textContent = new Date().toLocaleDateString(undefined, {
      weekday: "long", month: "long", day: "numeric", year: "numeric"
    });

