    if (!p) {
      noPatient.style.display = "";
      patientView.style.display = "none";
      return;
    }
    noPatient.style.display = "none";
    patientView.style.display = "";

    document.getElementById("currentPatientName").textContent = p.name;
    document.getElementById("todayDate").textContent = new Date().toLocaleDateString(undefined, {
      weekday: "long", month: "long", day: "numeric", year: "numeric"
    });

    const vl = document.getElementById("visitList");
    vl.innerHTML = "";
    if (p.visits.length === 0) {
      vl.innerHTML = '<p class="empty">No visits recorded yet.</p>';
    }
    p.visits.forEach(v => {
      const div = document.createElement("div");
      div.className = "visit";
      div.innerHTML = `
        <div class="date">${formatDate(v.date)}</div>
        <div class="note">${escapeHtml(v.note)}</div>
        <div class="actions">
          <button title="Edit">✏️</button>
          <button title="Delete">🗑️</button>
        </div>
      `;
      const [editBtn, delBtn] = div.querySelectorAll(".actions button");
      editBtn.onclick = () => editVisit(v.id);
      delBtn.onclick = () => deleteVisit(v.id);
      vl.appendChild(div);
    });
  }

  function escapeHtml(s) {
    return s.replace(/[&<>"']/g, c => ({
      "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;"
    }[c]));
  }

  // Cmd/Ctrl+Enter saves visit note
  document.getElementById("newNote").addEventListener("keydown", e => {
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
      e.preventDefault();
      addVisit();
    }
  });

  render();
</script>
</body>
</html>
```

## How to use it

1. **Save the code** above as `physio-notes.html` (or any name ending in `.html`)
2. **Double-click the file** to open it in any modern browser — no installation or server needed
3. **Add patients** using the field on the left
4. **Click a patient** to see their visits
5. **Type a note** and click Save (or press `Ctrl/Cmd + Enter`) to record a visit

## Features

- **Multiple patients** with an alphabetical list showing visit counts
- **Timestamped visit notes** (auto-stamped with date/time when saved)
- **Edit or delete** individual notes, delete entire patients
- **Auto-saves** everything to your browser's local storage — persists between sessions
- **Fully offline** — no internet, no accounts, no data sent anywhere
- Works on **desktop, tablet, and phone**

## Privacy note

All data stays **on your device** in the browser's storage — nothing is uploaded. That said, this means:
- Data is tied to one browser on one device (won't sync between devices)
- Clearing browser data will erase the notes
- For clinical records with legal retention requirements, consider adding an **"Export all data"** button (backup as JSON) — happy to add that if you'd like
- For multi-device access or formal compliance (HIPAA/GDPR), you'd want a proper database-backed version

